create function pg_temp.context_cost(p_key text,p_changes jsonb default '{}'::jsonb) returns jsonb language sql as $fn$
with input as (select '{"household_id": "28000100-0000-4000-8000-000000000001", "description": " Flight ", "amount_cents": 101, "payer_member_id": "28000000-0000-4000-8000-000000000001", "allocations": [{"memberId": "28000000-0000-4000-8000-000000000001", "allocatedCents": 51}, {"memberId": "28000000-0000-4000-8000-000000000002", "allocatedCents": 50}], "occurred_on": "2026-09-05", "context_kind": "project", "context_id": "28000200-0000-4000-8000-000000000001", "booking_id": null, "category_id": null, "note": null, "receipt_path": null}'::jsonb || p_changes as v)
select public.post_contextual_expense((v->>'household_id')::uuid,v->>'description',(v->>'amount_cents')::bigint,(v->>'payer_member_id')::uuid,v->'allocations',(v->>'occurred_on')::date,p_key,v->>'context_kind',(v->>'context_id')::uuid,(v->>'category_id')::uuid,v->>'note',v->>'receipt_path',(v->>'booking_id')::uuid) from input; $fn$;
select set_config('request.jwt.claim.sub','28000000-0000-4000-8000-000000000001',true);
set local role anon;
select throws_ok($$select pg_temp.context_cost('anon')$$,'42501',null,'anonymous role cannot post');
