select throws_ok($$select pg_temp.context_cost('missing-context','{"context_id": "28000500-0000-4000-8000-000000000001"}'::jsonb)$$,'42501',null,'missing parent is unavailable');
select throws_ok($$select pg_temp.context_cost('wrong-booking','{"booking_id": "28000500-0000-4000-8000-000000000002"}'::jsonb)$$,'22023',null,'booking must match project');
