select throws_ok($$select pg_temp.context_cost('no-array','{"allocations": null}'::jsonb)$$,'22023',null,'null allocations rejected');
select throws_ok($$select pg_temp.context_cost('negative','{"amount_cents": -1}'::jsonb)$$,'22023',null,'negative CHF rejected');
select throws_ok($$select pg_temp.context_cost('unsafe','{"amount_cents": 9007199254740992}'::jsonb)$$,'22023',null,'unsafe CHF rejected');
select throws_ok($$select pg_temp.context_cost('wrong-total','{"amount_cents": 100}'::jsonb)$$,'23514',null,'allocation sum must equal exact amount');
select throws_ok($$select pg_temp.context_cost('wrong-payer','{"payer_member_id": "28000000-0000-4000-8000-000000000003"}'::jsonb)$$,'23503',null,'payer must be household member');
select throws_ok($$select pg_temp.context_cost('foreign-receipt','{"receipt_path": "28000100-0000-4000-8000-000000000002/receipts/28000000-0000-4000-8000-000000000001.pdf"}'::jsonb)$$,'22023',null,'receipt must belong to household');
select throws_ok($$select pg_temp.context_cost('wrong-purpose','{"receipt_path": "28000100-0000-4000-8000-000000000001/documents/28000000-0000-4000-8000-000000000001.pdf"}'::jsonb)$$,'22023',null,'expense requires receipts namespace');
select is((select count(*) from public.financial_events where household_id='28000100-0000-4000-8000-000000000001'),0::bigint,'rejected commands leave no financial events');
select is((select count(*) from public.household_financial_links where household_id='28000100-0000-4000-8000-000000000001'),0::bigint,'rejected commands leave no cost links');
