select set_config('request.jwt.claim.sub','28000000-0000-4000-8000-000000000002',true);
select is(pg_temp.context_cost('first','{"booking_id": "28000500-0000-4000-8000-000000000001"}'::jsonb),current_setting('test.context.result')::jsonb,'partner can acknowledge identical same-household retry');
select set_config('request.jwt.claim.sub','28000000-0000-4000-8000-000000000001',true);
select throws_ok($$select pg_temp.context_cost('first','{"booking_id": "28000500-0000-4000-8000-000000000001", "description": "Different"}'::jsonb)$$,'22023',null,'retry binds description');
