select throws_ok($$select pg_temp.context_cost('first','{"booking_id": "28000500-0000-4000-8000-000000000001", "category_id": "28000500-0000-4000-8000-000000000001"}'::jsonb)$$,'22023',null,'retry binds category_id');
select throws_ok($$select pg_temp.context_cost('first','{"booking_id": "28000500-0000-4000-8000-000000000001", "note": "New note"}'::jsonb)$$,'22023',null,'retry binds note');
select throws_ok($$select pg_temp.context_cost('first','{"booking_id": "28000500-0000-4000-8000-000000000001", "receipt_path": "28000100-0000-4000-8000-000000000001/receipts/28000700-0000-4000-8000-000000000001.pdf"}'::jsonb)$$,'22023',null,'retry binds receipt_path');
