select throws_ok($$select pg_temp.context_cost('first','{"booking_id": "28000500-0000-4000-8000-000000000001", "context_id": "28000200-0000-4000-8000-000000000002"}'::jsonb)$$,'22023',null,'retry binds context_id');
select throws_ok($$select pg_temp.context_cost('first','{"booking_id": null}'::jsonb)$$,'22023',null,'retry binds booking_id');
select is((select count(*) from public.financial_events where household_id='28000100-0000-4000-8000-000000000001'),1::bigint,'identical and changed retries create exactly one event');
select is((select count(*) from public.household_financial_links where household_id='28000100-0000-4000-8000-000000000001'),1::bigint,'exactly one context link');
select is((select sum(receivable_delta_cents) from public.ledger_entries where household_id='28000100-0000-4000-8000-000000000001'),0::numeric,'linked expense ledger remains zero sum');
select is((select receivable_delta_cents from public.ledger_entries where household_id='28000100-0000-4000-8000-000000000001' and member_id='28000000-0000-4000-8000-000000000001'),50::bigint,'odd cent stays with payer and partner owes50');
select is(public.read_household_cost_context('project','28000200-0000-4000-8000-000000000001',p_booking_id=>'28000500-0000-4000-8000-000000000001')->>'paid_cents','101','cancelled unarchived booking accepts actual paid cost');
select is(public.read_household_cost_context('project','28000200-0000-4000-8000-000000000001')->>'paid_cents','101','project derives the same exact paid cost');
select lives_ok($$select public.post_manual_expense('28000100-0000-4000-8000-000000000001','Flight',101,'28000000-0000-4000-8000-000000000001','[{"memberId": "28000000-0000-4000-8000-000000000001", "allocatedCents": 51}, {"memberId": "28000000-0000-4000-8000-000000000002", "allocatedCents": 50}]','2026-09-05','manual-first')$$,'manual expense may arrive before contextual request');
select throws_ok($$select pg_temp.context_cost('manual-first','{}'::jsonb)$$,'22023',null,'existing manual receipt cannot be attached by contextual request');
select is((select count(*) from public.household_financial_links where household_id='28000100-0000-4000-8000-000000000001'),1::bigint,'manual-first collision never adds a link');
select is(public.post_manual_expense('28000100-0000-4000-8000-000000000001','Flight',101,'28000000-0000-4000-8000-000000000001','[{"memberId": "28000000-0000-4000-8000-000000000001", "allocatedCents": 51}, {"memberId": "28000000-0000-4000-8000-000000000002", "allocatedCents": 50}]','2026-09-05','first')->>'financial_event_id',current_setting('test.context.result')::jsonb->>'event_id','context-first manual replay cannot create a second event');
select ok(exists(select 1 from pg_locks where locktype='advisory' and pid=pg_backend_pid() and granted and mode='ExclusiveLock' and objsubid=1 and classid=((hashtextextended('28000100-0000-4000-8000-000000000001:first',0)>>32)&4294967295)::oid and objid=(hashtextextended('28000100-0000-4000-8000-000000000001:first',0)&4294967295)::oid),'wrapper retains the existing money-key advisory lock until transaction completion');
select public.assign_expense_context(l.household_id,l.financial_event_id,l.revision,'28000900-0000-4000-8000-000000000001',null,null) from public.household_financial_links l where household_id='28000100-0000-4000-8000-000000000001' and financial_event_id=(current_setting('test.context.result')::jsonb->>'event_id')::uuid;
-- Archive the booking while its parent is still editable.
update public.trip_bookings set archived_at=now() where id='28000500-0000-4000-8000-000000000001';
update public.household_projects set archived_at=now() where id='28000200-0000-4000-8000-000000000001';
select is(pg_temp.context_cost('first','{"booking_id": "28000500-0000-4000-8000-000000000001"}'::jsonb),current_setting('test.context.result')::jsonb,'identical replay succeeds after parent and booking archive');
select ok((select archived_at is not null from public.household_financial_links where household_id='28000100-0000-4000-8000-000000000001' and financial_event_id=(current_setting('test.context.result')::jsonb->>'event_id')::uuid),'replay does not restore archived cost link');
select throws_ok($$select pg_temp.context_cost('new-archived-parent','{}'::jsonb)$$,'22023',null,'archived parent rejects new expense');
update public.household_projects set archived_at=null where id='28000200-0000-4000-8000-000000000001';
select throws_ok($$select pg_temp.context_cost('new-archived-booking','{"booking_id": "28000500-0000-4000-8000-000000000001"}'::jsonb)$$,'22023',null,'archived booking rejects new expense');
update public.trip_bookings set archived_at=null where id='28000500-0000-4000-8000-000000000001';
select public.assign_expense_context(l.household_id,l.financial_event_id,l.revision,'28000900-0000-4000-8000-000000000002','project','28000200-0000-4000-8000-000000000002'::uuid) from public.household_financial_links l where household_id='28000100-0000-4000-8000-000000000001' and financial_event_id=(current_setting('test.context.result')::jsonb->>'event_id')::uuid;
select is(pg_temp.context_cost('first','{"booking_id": "28000500-0000-4000-8000-000000000001"}'::jsonb),current_setting('test.context.result')::jsonb,'replay acknowledges event after partner reassigned its context');
select is((select project_id from public.household_financial_links where household_id='28000100-0000-4000-8000-000000000001' and financial_event_id=(current_setting('test.context.result')::jsonb->>'event_id')::uuid),'28000200-0000-4000-8000-000000000002'::uuid,'replay preserves the partner chosen context');
select lives_ok($$select pg_temp.context_cost('asset','{"context_kind": "asset", "context_id": "28000300-0000-4000-8000-000000000001"}'::jsonb)$$,'posts an appliance cost');
select lives_ok($$select pg_temp.context_cost('commitment','{"context_kind": "commitment", "context_id": "28000400-0000-4000-8000-000000000001"}'::jsonb)$$,'ended commitment can still record its final bill');
select is(public.read_household_cost_context('asset','28000300-0000-4000-8000-000000000001')->>'paid_cents','101','asset exact paid total');
update public.household_assets set archived_at=now() where id='28000300-0000-4000-8000-000000000001';
select throws_ok($$select pg_temp.context_cost('new-asset','{"context_kind": "asset", "context_id": "28000300-0000-4000-8000-000000000001"}'::jsonb)$$,'22023',null,'archived asset rejects new expense');
select lives_ok($$select pg_temp.context_cost('asset','{"context_kind": "asset", "context_id": "28000300-0000-4000-8000-000000000001"}'::jsonb)$$,'identical asset replay still acknowledges original cost');
select is(public.read_household_cost_context('commitment','28000400-0000-4000-8000-000000000001')->>'paid_cents','101','commitment exact paid total');
update public.household_commitments set archived_at=now() where id='28000400-0000-4000-8000-000000000001';
select throws_ok($$select pg_temp.context_cost('new-commitment','{"context_kind": "commitment", "context_id": "28000400-0000-4000-8000-000000000001"}'::jsonb)$$,'22023',null,'archived commitment rejects new expense');
select lives_ok($$select pg_temp.context_cost('commitment','{"context_kind": "commitment", "context_id": "28000400-0000-4000-8000-000000000001"}'::jsonb)$$,'identical commitment replay still acknowledges original cost');
reset role;
create function pg_temp.reject_context_link() returns trigger language plpgsql as $$ begin raise exception 'fixture rejects link' using errcode='23514'; end $$;
create trigger contextual_rollback_probe before insert on public.household_financial_links for each row execute function pg_temp.reject_context_link();
set local role authenticated;
select lives_ok($$select public.reserve_household_attachment('28000100-0000-4000-8000-000000000001/receipts/28000700-0000-4000-8000-000000000001.pdf','application/pdf')$$,'reserve private receipt using assembled attachment registry');
reset role;
insert into storage.objects(bucket_id,name,metadata) values('household-files','28000100-0000-4000-8000-000000000001/receipts/28000700-0000-4000-8000-000000000001.pdf','{"mimetype":"application/pdf"}');
set local role authenticated;
select set_config('test.context.before_events',(select count(*)::text from public.financial_events where household_id='28000100-0000-4000-8000-000000000001'),true);
select set_config('test.context.before_activity',(select count(*)::text from public.activity_events where household_id='28000100-0000-4000-8000-000000000001'),true);
select throws_ok($$select pg_temp.context_cost('rollback','{"receipt_path": "28000100-0000-4000-8000-000000000001/receipts/28000700-0000-4000-8000-000000000001.pdf"}'::jsonb)$$,'23514',null,'link failure rolls back the newly posted event and receipt claim');
select is((select count(*)::text from public.financial_events where household_id='28000100-0000-4000-8000-000000000001'),current_setting('test.context.before_events'),'ledger event count unchanged after link failure');
select is((select count(*)::text from public.activity_events where household_id='28000100-0000-4000-8000-000000000001'),current_setting('test.context.before_activity'),'activity also rolls back');
select is((select state from public.household_attachment_uploads where path='28000100-0000-4000-8000-000000000001/receipts/28000700-0000-4000-8000-000000000001.pdf'),'pending','attachment claim rolls back with failed linked expense');
select is((select count(*) from public.money_command_receipts where household_id='28000100-0000-4000-8000-000000000001' and idempotency_key='rollback'),0::bigint,'manual retry receipt rolls back');
reset role;
select is((select count(*) from private.contextual_expense_receipts where household_id='28000100-0000-4000-8000-000000000001' and idempotency_key='rollback'),0::bigint,'context retry receipt rolls back');
drop trigger contextual_rollback_probe on public.household_financial_links;
set local role authenticated;
select lives_ok($$select pg_temp.context_cost('rollback','{"receipt_path": "28000100-0000-4000-8000-000000000001/receipts/28000700-0000-4000-8000-000000000001.pdf"}'::jsonb)$$,'same key and receipt can safely retry after rollback');
select is((select state from public.household_attachment_uploads where path='28000100-0000-4000-8000-000000000001/receipts/28000700-0000-4000-8000-000000000001.pdf'),'claimed','successful linked expense claims its actual receipt');
select lives_ok($$select pg_temp.context_cost('rollback','{"receipt_path": "28000100-0000-4000-8000-000000000001/receipts/28000700-0000-4000-8000-000000000001.pdf"}'::jsonb)$$,'identical retry does not reclaim an already claimed receipt');
select throws_ok($$select pg_temp.context_cost('missing-upload','{"receipt_path": "28000100-0000-4000-8000-000000000001/receipts/28000700-0000-4000-8000-000000000002.pdf"}'::jsonb)$$,'22023',null,'unuploaded receipt rejected by financial attachment boundary');
select set_config('request.jwt.claim.sub','28000000-0000-4000-8000-000000000003',true);
select throws_ok($$select pg_temp.context_cost('first','{"booking_id": "28000500-0000-4000-8000-000000000001"}'::jsonb)$$,'42501',null,'outsider cannot replay a known existing receipt key');
select is((select count(*) from public.household_financial_links where household_id='28000100-0000-4000-8000-000000000001'),0::bigint,'cost links remain tenant isolated');
select throws_ok($$select * from private.contextual_expense_receipts$$,'42501',null,'private receipt payload cannot be selected directly');
reset role;
select is((select count(*) from private.contextual_expense_receipts where household_id='28000100-0000-4000-8000-000000000001'),4::bigint,'only four successful contextual commands own private receipts');
-- Interleaving proof: the same advisory lock serializes both arrival orders tested above.
-- A waiter cannot observe the manual receipt without the contextual receipt/link because
-- post_manual_expense and both inserts commit together; rollback removes all three.
select * from finish();
rollback;
